{"command": "python3 <<'PY'
import hashlib, base64, subprocess, tempfile, os, shutil
def b64(d): return base64.b64encode(hashlib.sha256(d).digest()).decode()
def b64d(s): return base64.b64decode(s.split(":")[1])

# Let's collect more data points for dir hashing
def get(files):
    d=tempfile.mkdtemp(); mig=os.path.join(d,"migs"); os.makedirs(mig)
    for n,c in files.items(): open(os.path.join(mig,n),"wb").write(c)
    subprocess.run(["/workspace/executable","migrate","hash","--dir",f"file://{mig}"], capture_output=True, cwd="/tmp")
    s=open(os.path.join(mig,"atlas.sum")).read()
    shutil.rmtree(d)
    # parse
    lines=s.strip().splitlines()
    dirh=lines[0]
    per={l.split()[0]:l.split()[1] for l in lines[1:]}
    return dirh, per

# Single file cases
for fn,c in [("a.sql",b""),("a.sql",b"hello"),("b.sql",b""),("b.sql",b"hello")]:
    dirh,per=get({fn:c})
    print(f"{fn} {repr(c)} dir={dirh} file={per[fn]}")
    # Try to see relation: dir = sha( file_hash + something )?
    # Let's try dir = sha( fn + content + "dir"? ) No
PY"}

