{"command": "python3 <<'PY'
import hashlib, base64, itertools
def b64(d): return base64.b64encode(hashlib.sha256(d).digest()).decode()
def b64d(s): return base64.b64decode(s)

cases=[
 (b"a.sql", b"", b64d("CoCP3kfKMOOxxDxOuas5B15gB/eJYayV6IaeyG8CAaY="), "WA5oHrvieLh9w5UPHLK+AMpH0EO9JE2HrFfp3Fj8WVw="),
 (b"a.sql", b"hello", b64d("8moOy2s6mETtoltLuN83ids72g58/XdFQAisc8HwJ2s="), "u2ihVVvMHEytq2R/u0P3HmDf8EzneOZltBTFU3ceMj8="),
 (b"b.sql", b"", b64d("BEkDXhMGtSqWo5ROzsTTDehNjSt2F+YRkitJnAmlurg="), "WTd70JwMlDL7wB/JQMU9MJcSR0SHEFu9JRT0veVnGBM="),
 (b"b.sql", b"hello", b64d("IXjwpIruS5ScxiKQk2m0lnyGjKWB6T9O9Tm0u1oaOlM="), "TGKNGvQqt1ihzK9Ku1rvqfjaCY2t7mWL+fP9aOt9r/A="),
]
# Try dir = sha( X ) where X is combination of fn, content, file_bytes, file_hex, file_b64, with separators
# Let's generate X templates: e.g., X = fn + content + file_bytes, etc.
# We'll brute force templates with up to 3 components
components = ["fn","content","fb","hex","b64str","h1str"]
# fb = file_bytes, hex = hex string, b64str = base64 without prefix, h1str = with prefix
seps = [b"", b"\n", b" ", b"  ", b":"]

def get_comp(name, fn, content, fb):
    if name=="fn": return fn
    if name=="content": return content
    if name=="fb": return fb
    if name=="hex": return fb.hex().encode()
    if name=="b64str": return base64.b64encode(fb).decode().encode()
    if name=="h1str": return (b"h1:"+base64.b64encode(fb).decode().encode())

# Try 2-component combos: X = comp1 + sep + comp2
found=[]
for c1 in components:
    for c2 in components:
        for sep in seps:
            ok=True
            for fn,content,fb,exp in cases:
                X = get_comp(c1,fn,content,fb) + sep + get_comp(c2,fn,content,fb)
                if b64(X)!=exp:
                    ok=False
                    break
            if ok:
                print(f"MATCH {c1} + {repr(sep)} + {c2}")
                found.append((c1,sep,c2))
print("2-comp done",len(found))
# Try 3-component? Might be many, but try limited
PY"}

