# === Config (project file) handling ===
import re as _re

def parse_hcl_project(content, filename, var_overrides, env_name):
    # Returns (env_dict, error_msg) where env_dict is dict of env attributes (url, dev, etc.)
    # var_overrides: dict from --var
    # env_name: selected env or ""
    # Steps: parse variable blocks, locals, env blocks
    # For simplicity, implement line-based block parsing with brace counting and string awareness
    # First, check for malformed syntax that HCL would reject: e.g., line with "invalid syntax here {{"
    # We'll attempt to parse and on failure return HCL diagnostic
    try:
        blocks = parse_hcl_blocks(content, filename)
    except HCLDiagnostic as e:
        return None, str(e)
    # blocks: list of (type, labels, body_str, start_line)
    variables = {}  # name -> (type, default, has_default)
    locals_dict = {}
    envs = {}
    # First pass: variables
    for btype, labels, body, start in blocks:
        if btype == "variable" and len(labels) == 1:
            vname = labels[0]
            attrs = parse_hcl_attrs(body, filename, start)
            if isinstance(attrs, str):  # error
                return None, attrs
            vtype = attrs.get("type", "string")
            # vtype may be like "string" (ident) – keep as is
            if "default" in attrs:
                variables[vname] = (vtype, attrs["default"], True)
            else:
                variables[vname] = (vtype, None, False)
        elif btype == "locals" and len(labels) == 0:
            attrs = parse_hcl_attrs(body, filename, start)
            if isinstance(attrs, str):
                return None, attrs
            for k, v in attrs.items():
                locals_dict[k] = v
        elif btype == "env" and len(labels) == 1:
            ename = labels[0]
            attrs = parse_hcl_attrs(body, filename, start)
            if isinstance(attrs, str):
