def eval_hcl_expr(raw, var_values, locals_values, env_name, filename_for_err=None, content_for_err=None):
    raw = raw.strip()
    # Handle lists: [ ... ]
    if raw.startswith("[") and raw.endswith("]"):
        inner = raw[1:-1].strip()
        if inner == "":
            return []
        # Split by comma outside strings/brackets/parens?
        parts = split_hcl_list(inner)
        return [eval_hcl_expr(p, var_values, locals_values, env_name, filename_for_err, content_for_err) for p in parts]
    # Handle strings with interpolation: "..." 
    if raw.startswith('"') and raw.endswith('"') and len(raw) >= 2:
        inner = raw[1:-1]
        # Unescape? Keep as is, but handle ${...} interpolation and escapes?
        # Process escapes: \" \\ \n etc.? For our URLs, no escapes. Simplify: handle \\ and \"?
        # Interpolate ${...}
        def repl(m):
            expr = m.group(1).strip()
            v = eval_simple_ref(expr, var_values, locals_values, env_name)
            # v may be string or other? Convert to string
            if isinstance(v, list):
                # Lists inside strings? Not expected. Convert?
                return ",".join(str(x) for x in v)
            return str(v)
        # Find ${...} with nesting? Simple: \$\{([^}]+)\}
        import re
        # Need to handle var.missing error with diagnostic? eval_simple_ref will raise HCLEVALError with varname
        try:
            res = re.sub(r'\$\{([^}]+)\}', lambda m: repl(m), inner)
        except HCLEVALError as e:
            raise e
        # Unescape: replace \\ with \, \" with ", etc.? For URLs, not needed. Keep simple: decode escapes?
        # Python's unicode_escape? But that would mangle. Just handle \" and \\ and \n?
        res = res.replace('\\"', '"').replace('\\\\', '\\').replace('\\n', '\n').replace('\\t', '\t')
        return res
    # Handle function call getenv("...")?
    m = re.match(r'getenv\s*\(\s*"([^"]*)"\s*\)\s*$', raw)
    if m:
        var = m.group(1)
        return os.environ.get(var, "")
    # Handle simple references: var.xxx, local.xxx, atlas.env
    if re.match(r'^(var|local|atlas)\.', raw) or raw == "atlas.env":
        return eval_simple_ref(raw, var_values, locals_values, env_name)
    # Handle bare atlas.env without prefix? Already.
    # Handle numbers, bools, null?
    if raw in ("true", "True"):
