    if raw in ("false", "False"):
        return False
    if raw == "null":
        return None
    # Try number?
    try:
        if "." in raw:
            return float(raw)
        else:
            return int(raw)
    except:
        pass
    # Handle ident like "string", "int"? For variable type, return as string? e.g., type = string (no quotes) -> should be "string"?
    if re.match(r'^[A-Za-z_][A-Za-z0-9_-]*$', raw):
        return raw
    # Handle unquoted? Return as is?
    return raw

