def split_hcl_list(inner):
    parts = []
    cur = ""
    depth_b = 0
    depth_p = 0
    depth_br = 0
    in_s = False
    esc = False
    for ch in inner:
        if in_s:
            cur += ch
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_s = False
        else:
            if ch == '"':
                in_s = True
                cur += ch
            elif ch == "[":
                depth_b += 1
                cur += ch
            elif ch == "]":
                depth_b -= 1
                cur += ch
            elif ch == "(":
                depth_p += 1
                cur += ch
            elif ch == ")":
                depth_p -= 1
                cur += ch
            elif ch == "{":
                depth_br += 1
                cur += ch
            elif ch == "}":
                depth_br -= 1
                cur += ch
            elif ch == "," and depth_b == 0 and depth_p == 0 and depth_br == 0:
                parts.append(cur.strip())
