def split_sql_statements(sql):
    # Split by ; outside strings/parens? For sqlite, statements end with ; . Simple: split by ; outside strings?
    stmts = []
    cur = ""
    in_s = False
    s_char = None
    esc = False
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if in_s:
            cur += ch
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == s_char:
                # Check for doubled quote? e.g., '' inside ''? For simplicity, if next char same, consume?
                if i+1 < n and sql[i+1] == s_char:
                    cur += sql[i+1]
                    i += 1
                else:
                    in_s = False
            i += 1
        else:
            if ch in ("'", '"', "`"):
                # ` is identifier quote, treat similarly? For splitting, `...` may contain ;? Unlikely. Treat as string.
                in_s = True
                s_char = ch
                cur += ch
                i += 1
            elif ch == "-" and i+1 < n and sql[i+1] == "-":
                # line comment until newline
                # Include comment? For splitting, skip? Actually comments should be ignored for parsing, but keep? For our parsing, remove comments? Simpler: skip to newline
                nl = sql.find("\n", i)
                if nl == -1:
                    break
                i = nl + 1
                cur += "\n"
            elif ch == "/" and i+1 < n and sql[i+1] == "*":
                end = sql.find("*/", i+2)
                if end == -1:
                    break
                i = end + 2
            elif ch == ";":
                cur += ch
                stmts.append(cur)
                cur = ""
                i += 1
            else:
                cur += ch
                i += 1
    if cur.strip():
        stmts.append(cur)
    return stmts

def split_sql_columns(cols_def):
    # Split by comma outside parens/strings?
    parts = []
    cur = ""
    depth = 0
    in_s = False
    s_char = None
    esc = False
    for ch in cols_def:
        if in_s:
            cur += ch
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == s_char:
                in_s = False
        else:
            if ch in ("'", '"', "`"):
                in_s = True
                s_char = ch
                cur += ch
            elif ch == "(":
                depth += 1
                cur += ch
            elif ch == ")":
                depth -= 1
                cur += ch
            elif ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
    if cur.strip():
        parts.append(cur)
    return parts

