                    for c in columns:
                        if c["name"] == cname_clean:
                            c["pk"] = idx + 1
                            break
            # Handle inline PKs already set? Need to ensure pk list
            # Collect pk
            pk_list = sorted([c for c in columns if c["pk"] > 0], key=lambda x: x["pk"])
            # Handle inline FKs: convert to fks
            for c in columns:
                if c.get("inline_fk"):
                    fk = {"id": len(fks), "table": c["inline_fk"]["table"], "from": [c["name"]], "to": c["inline_fk"]["to"], "on_update": "NO ACTION", "on_delete": "NO ACTION"}
                    fks.append(fk)
                    del c["inline_fk"]
                if "auto" in c:
                    del c["auto"]  # will handle via auto set?
            # Build auto set
            auto_set = set(c["name"] for c in columns if c.get("auto", False))
            for c in columns:
                if "auto" in c:
                    del c["auto"]
            # Clean columns: remove pk temp? Keep pk for later, but for internal need pk field
            # For internal, columns need pk order, already.
            tables.append({"name": tname, "sql": s, "columns": columns, "pk": pk_list, "fks": fks, "indexes": [], "auto": auto_set})
        # Check for CREATE INDEX?
        mi = re.match(r'CREATE\s+(UNIQUE\s+)?INDEX\s+(?:IF\s+NOT\s+EXISTS\s+)?[`"]?(\w+)[`"]?\s+ON\s+[`"]?(\w+)[`"]?\s*\((.*)\)', s, re.IGNORECASE | re.DOTALL)
        if mi:
            unique = bool(mi.group(1))
            iname = mi.group(2)
            tname = mi.group(3)
            cols_part = mi.group(4)
            cols = [c.strip().strip('`"[]').split()[0] for c in cols_part.split(",")]
            # Find table and add index
            for t in tables:
                if t["name"] == tname:
                    t["indexes"].append({"name": iname, "unique": unique, "columns": cols, "origin": "c"})
                    break
            else:
                # Table not yet seen? Store for later? For simplicity, create placeholder? Actually CREATE INDEX after CREATE TABLE, so table already seen. Good.
                pass
            continue
    return {"schemas": [{"name": "main", "tables": tables}]}

def split_sql_statements(sql):
    # Split by ; outside strings/parens? For sqlite, statements end with ; . Simple: split by ; outside strings?
    stmts = []
    cur = ""
    in_s = False
    s_char = None
    esc = False
    i = 0
    n = len(sql)
    while i < n:
        ch = sql[i]
        if in_s:
            cur += ch
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == s_char:
                # Check for doubled quote? e.g., '' inside ''? For simplicity, if next char same, consume?
                if i+1 < n and sql[i+1] == s_char:
                    cur += sql[i+1]
                    i += 1
                else:
                    in_s = False
            i += 1
        else:
            if ch in ("'", '"', "`"):
                # ` is identifier quote, treat similarly? For splitting, `...` may contain ;? Unlikely. Treat as string.
                in_s = True
                s_char = ch
                cur += ch
                i += 1
            elif ch == "-" and i+1 < n and sql[i+1] == "-":
                # line comment until newline
                # Include comment? For splitting, skip? Actually comments should be ignored for parsing, but keep? For our parsing, remove comments? Simpler: skip to newline
                nl = sql.find("\n", i)
                if nl == -1:
                    break
                i = nl + 1
                cur += "\n"
            elif ch == "/" and i+1 < n and sql[i+1] == "*":
                end = sql.find("*/", i+2)
                if end == -1:
                    break
                i = end + 2
            elif ch == ";":
                cur += ch
                stmts.append(cur)
                cur = ""
                i += 1
            else:
                cur += ch
                i += 1
    if cur.strip():
        stmts.append(cur)
    return stmts

def split_sql_columns(cols_def):
    # Split by comma outside parens/strings?
    parts = []
    cur = ""
    depth = 0
    in_s = False
    s_char = None
    esc = False
    for ch in cols_def:
        if in_s:
            cur += ch
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == s_char:
                in_s = False
        else:
            if ch in ("'", '"', "`"):
                in_s = True
                s_char = ch
                cur += ch
            elif ch == "(":
                depth += 1
                cur += ch
            elif ch == ")":
                depth -= 1
                cur += ch
            elif ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
    if cur.strip():
        parts.append(cur)
    return parts

